# Frozen Duck Core engine v4_0: generated by tools/freeze_engine.py from 79cc25d:src/duckmind/duckcore/nest.py; do not edit.
"""The charging nest (Duck Core v4, part B): the mother duck's wing.

The nest is an open, flat pad at the mat (0, 0) with its opening toward +x, ring contacts
under the belly and a marker (owner decision D1, 2026-09-26). Sitting on the contacts the
duck charges (``nested``) at any heading; standing up breaks them, so it can never walk
while plugged in. A full battery makes it want to go out; the lower the battery, the
likelier an outing ends back home. It always keeps enough for the way home
(``threshold``), finds its way back leg by leg, walks in and sits down the way it came
(never turning round on the spot), and leaves by standing up and walking a right arc
forward. A miss means a forward loop out and in again (never backing out), and three
misses mean sitting beside the nest and asking for a hand. It sleeps in the nest at night,
rests there while the family is out, and a fall near the nest never teaches it to fear its
own nest.

Simulator only for now (owner decision 2026-09-26): ``HardwareConfig.nest`` is off on the
real robot until the nest hardware exists. Integers only; draws through the core's
counters; every decision and outcome is an L1 event.
"""

from __future__ import annotations

from datetime import timedelta
from typing import TYPE_CHECKING, Any

from duckmind.engines.v4_0.duckcore import content, daycycle, moments, rng
from duckmind.engines.v4_0.duckcore.fixed import SCALE, atan2_mrad, clamp, isqrt, signed_mrad

if TYPE_CHECKING:
    from duckmind.engines.v4_0.duckcore.engine import DuckCore
    from duckmind.engines.v4_0.provenance import Event

N: dict[str, Any] = content.NEST
# Off the nest, it heads home this far above the line (a minute of standing drain and a
# reflex or two can pass before its next look at the battery).
HOME_MARGIN = 500
# The way home, as threshold() prices it (seconds; see there).
TURN_HOME_S = 11  # the tight arc round toward home: up to half a turn at ~0.3 rad/s
DOCK_LEG_S = 6  # the leg in
RETRY_WALK_S = 30  # a miss: a forward loop out and round, and the way in again
RETRY_LEGS = 3  # …with a look before each of its legs
LEG_MM = 660  # a 6 s leg at ~0.11 m/s
LOOK_S = 4  # the longest look between two legs home (NEST["home_pause_s"])
TRY_STAND_S = 20  # one try at sitting down: stand, look, sit onto the contacts
RETRY_AFTER_MIN = 5  # stranded beside the nest after three misses: rest this long, try again
R: dict[str, Any] = content.RHYTHM
STAGE_LEAVE: dict[str, int] = N["leave"]
BID_TEXT = {
    "carry_me_home": "我走不動了，可以抱我回窩嗎？",
    "nest_help": "我進不去窩，可以幫我放進去嗎？",
    "help": "我跌倒了，翻不回來，可以扶我一下嗎？",
    "bedtime": "我來不及走回窩，就在這裡睡了；可以抱我回窩嗎？",
}


def _e() -> Any:
    """The engine module (imported lazily: the engine imports this one)."""
    from duckmind.engines.v4_0.duckcore import engine

    return engine


def dist_mm(core: DuckCore) -> int:
    s = core.s
    return isqrt(s.pos_x * s.pos_x + s.pos_y * s.pos_y)


def threshold(core: DuckCore) -> int:
    """The battery it keeps for the way home from here (home-base-v1), on top of the 30%
    floor below which it never walks: what the way home can cost now that every turn is
    walked (a tight arc at ~0.11 m/s and ~0.3 rad/s) and legs are whole seconds, ×1.5 and
    at least 5%.

    Walking: the straight way; the arc round toward home (up to half a turn); a second
    more per leg (whole seconds, the last at least MIN_WALK_S); the leg in; and one
    forward loop out and in again after a miss. Standing: a look between legs, and each
    try at sitting down onto the contacts. The ×1.5 covers a second miss."""
    E = _e()
    dist = dist_mm(core)
    legs = dist // LEG_MM + 2
    walk_s = dist // E.ACTUAL_SPEED_MM[0][1] + TURN_HOME_S + legs + DOCK_LEG_S + RETRY_WALK_S
    stand_s = (legs + RETRY_LEGS) * LOOK_S + int(N["dock_tries"]) * TRY_STAND_S
    walk_cost = E.BATTERY_DRAIN_PER_MIN + E.BATTERY_DRAIN_PER_MIN * E.STAND_DRAIN // SCALE
    stand_cost = E.BATTERY_DRAIN_PER_MIN * E.STAND_DRAIN // SCALE
    cost = walk_s * walk_cost // 60 + stand_s * stand_cost // 60
    reserve = max(int(N["reserve_min"]), cost * int(N["reserve_margin"]) // SCALE)
    return int(E.MIN_MOTION_BATTERY) + reserve


def low_for_a_walk(core: DuckCore) -> bool:
    """Its battery is down to the reserve for the way home (and a little): only the way
    home now, no walk of any other kind (not even a reflex turn off the nest)."""
    return core.s.battery <= threshold(core) + HOME_MARGIN


def leave_battery(core: DuckCore) -> int:
    """The battery at which it is fully willing to leave the nest: by age, and a bold duck
    ±5% sooner (its temperament)."""
    shift = int(content.TEMPERAMENT["leave_shift"])
    bold = int(core.s.temperament.get("boldness", 5000))
    return int(STAGE_LEAVE[core.stage().stage_id]) - (bold - 5000) * shift // 3000


# ---------------------------------------------------------------------------- the battery


def battery_minute(core: DuckCore) -> None:
    """Charge on the nest (net of what an awake duck uses), on the cable as before, drain
    everywhere else; 15% means sleep and 3% means switching off, as before."""
    E = _e()
    s = core.s
    if s.nested:
        if s.bedtime_done and s.battery > E.BEDTIME_BATTERY + 1000:
            s.bedtime_done = False  # charged again: the low-battery doze is over
        gain = core.hw.nest_charge_per_min
        if not core._until(s.napping_until):
            gain -= core.hw.nest_awake_drain
        if gain < 0:
            s.day_drain -= gain
        s.battery = clamp(s.battery + gain)
        return
    if s.docked:
        s.battery = min(SCALE, s.battery + E.CHARGE_PER_MIN)
        return
    if s.unplaced and s.need is None and s.battery < 4500:
        # Lifted and put down somewhere that is not its nest, and the battery is going:
        # it asks to be put back (a need, like being stranded).
        call_for_help(core, "carry_me_home", ())
    drain = E.BATTERY_DRAIN_PER_MIN
    if s.posture in E.STANDING:
        drain = drain * E.STAND_DRAIN // SCALE
    s.battery = max(0, s.battery - drain)
    s.day_drain += drain
    if s.battery <= E.BEDTIME_BATTERY and not s.bedtime_done:
        core._bedtime()
    if s.battery <= E.EMPTY_BATTERY:
        core.power_off(None, reason="battery_empty")
        return
    if s.battery < E.MIN_MOTION_BATTERY and s.stranded is None and s.floor:
        strand(core, "battery")


# ---------------------------------------------------------------------------- resting


def _can_walk(core: DuckCore) -> str | None:
    """Why it could not walk a leg right now (None: it can)."""
    E = _e()
    s = core.s
    if not s.floor or s.unplaced:
        return "unplaced"
    if s.docked:
        return "tethered"
    if not core.hw.pickup_detect:
        return "no_pickup_sensor"
    if not core.hw.motion_validated:
        return "unvalidated"
    if s.battery < E.MIN_MOTION_BATTERY:
        return "battery"
    if core._night():
        return "night"
    if "wander" not in s.unlocked:
        return "too_young"
    if s.stranded is not None:
        return "stranded"
    if (
        s.yielding
        or s.hot
        or core._until(s.stop_until)
        or core._until(s.lockout_until)
        or core._until(s.napping_until)
        or core._until(s.quiet_until)
    ):
        return "busy"
    return None


def _nap(core: DuckCore, reason: str) -> None:
    """Sleep where it sits (in the nest, as a rule): a real nap, or the night."""
    if reason == "quiet_hours":
        core._start_nap(True)
    elif reason == "away_rest":
        low, high = R["rest_bout_min"]
        minutes = int(low) + rng.pick_index(core._rand("cycle.rest"), int(high) - int(low) + 1)
        core._start_nap(False, minutes=minutes, reason="away_rest")
    else:
        core._start_nap(False)


def _tired(core: DuckCore) -> bool:
    E = _e()
    s = core.s
    if s.energy < E.SIT_ENERGY:
        return True
    return s.energy < 3000 and not core._present(3)


def maybe_rest(core: DuckCore) -> bool:
    """Night, winding down, nobody home or tired: home to the nest and rest there. True
    when that is what this minute is about (nothing else is decided)."""
    s = core.s
    if (
        s.homing is not None
        or s.excursion is not None  # its outing ends itself (and then decides about home)
        or s.posture in ("walk", "fallen")
        or core._until(s.napping_until)
    ):
        return False
    if core._until(s.nap_block_until) and s.phase not in ("wind_down",):
        # Just woken: no dozing off again yet, but the way home is never put off.
        if not (s.nested or s.docked) and s.stranded is None and s.floor:
            if s.battery <= threshold(core) + HOME_MARGIN:
                return _home_for_battery(core)
        return False
    phase = s.phase
    m = daycycle.minute_of_day(s.now)
    if phase in ("night", "wind_down") and s.posture in ("stand", "walk"):
        _sit(core, "night")  # standing in the nest (after the gamepad…) sits back onto it
    home = s.nested or s.docked
    if phase == "night":
        if not home and s.stranded is None and s.floor:
            strand(core, "bedtime")
        _sit(core, "night")
        _nap(core, "quiet_hours")
        return True
    if phase == "wind_down":
        if home:
            _goodnight(core)
            return True
        if m >= int(R["in_nest_by_min"]) or _can_walk(core) is not None:
            if s.floor and s.stranded is None:
                strand(core, "bedtime")
            _sit(core, "night")
            _nap(core, "quiet_hours")
            return True
        start_homing(core, "bedtime")
        return True
    if phase == "alone":
        if not home:
            since = daycycle.minutes_since(core, s.family_since) or 0
            if since <= int(N["alone_home_min"]) and _can_walk(core) is None:
                start_homing(core, "alone")
                return True
            if s.posture != "sit":
                _sit(core, "alone")
            if (s.stranded or {}).get("reason") == "dock_failed" and (
                s.battery >= _e().MIN_MOTION_BATTERY + 100
            ):
                # Beside the nest after three misses: it stays awake and tries again in a
                # few minutes (retry_stranded) instead of sleeping there while the battery
                # it would need for the nest drains away.
                return True
            _nap(core, "away_rest")
            return True
        if s.anticipating is not None and "predict" in s.anticipating:
            return True  # awake on the nest, watching the door
        if s.rest_spell_until is None:
            low, high = R["rest_spell_min"]
            spell = int(low) + rng.pick_index(core._rand("cycle.rest"), int(high) - int(low) + 1)
            s.rest_spell_until = s.now + timedelta(minutes=spell)
        if s.now >= s.rest_spell_until:
            s.rest_spell_until = None
            _nap(core, "away_rest")
        return True
    s.rest_spell_until = None
    if not home and s.stranded is None and s.floor and s.battery <= threshold(core) + HOME_MARGIN:
        if _home_for_battery(core):
            return True
    if phase == "solo" and s.solo_exc_s >= int(R["solo_excursion_max_min"]) * 60 and not home:
        if _can_walk(core) is None:
            start_homing(core, "solo_done")
            return True
    if _tired(core):
        if not home and _can_walk(core) is None and s.stranded is None:
            start_homing(core, "tired")
            return True
        _sit(core, "tired")
        _nap(core, "tired")
        return True
    return False


def _home_for_battery(core: DuckCore) -> bool:
    """The battery it keeps for the way home is nearly spent: home now, before anything
    (standing right in the nest, it only has to sit back down onto the contacts)."""
    s = core.s
    if dist_mm(core) <= int(N["funnel_mm"]):
        _sit(core, "home")
        if s.nested:
            return True
    if _can_walk(core) is None:
        start_homing(core, "battery")
        return True
    return False


def _sit(core: DuckCore, reason: str) -> None:
    if core.s.posture in ("stand", "walk"):
        core._sit_down_now(reason)


def _goodnight(core: DuckCore) -> None:
    """In the nest at bedtime: turn round, settle, 晚安咕～咕～, asleep before 22:00."""
    s = core.s
    s.bedtime_nest = True
    _sit(core, "bedtime")
    event = core._emit(
        "duck.bedtime",
        {
            "battery": s.battery,
            "sounds": ["coo", "coo"],
            "text": "回到窩裡坐好：晚安咕～咕～" if s.nested else "插著電線坐好：晚安咕～咕～",
            "in_nest": True,
        },
    )
    del event
    _nap(core, "quiet_hours")
    daycycle.set_phase(core, "night", "bedtime")


# ---------------------------------------------------------------------------- leaving


def maybe_leave(core: DuckCore) -> bool:
    """nest-leave-v1: on the nest, awake, the fuller the battery the likelier it sets off."""
    from duckmind.engines.v4_0.duckcore import excursion

    s = core.s
    if not s.nested or core._until(s.napping_until):
        return False
    if excursion.can_start(core) is not None:
        return False
    leave = leave_battery(core)
    low = int(N["leave_min"])
    willing = clamp((s.battery - low) * SCALE // max(1, leave - low))
    reunion = s.reunion_until is not None and s.now < s.reunion_until
    if willing <= 0 and not reunion:
        return False
    chance = int(N["nest_hazard"]) * willing // SCALE
    chance = chance * excursion.outing_mult(core) // SCALE
    reason = excursion.pick_reason(core)
    if reunion:
        chance = max(chance, 8000)
        reason = "social"
    raw = core._rand("nest.leave")
    go = rng.below(raw, chance)
    if not go:
        return False
    if not excursion.somewhere_to_go(core, reason):
        return False  # its leash and the spots it avoids leave it nowhere to go: it stays
    decision = core._emit(
        "duck.decision",
        {
            "verb": "stand_up",
            "rule": "nest-leave-v1",
            "trigger": reason,
            "from": "nest",
            "table": core.table,
            "counter": core.counters["nest.leave"],
            "draw": rng.unit(raw),
            "inputs": {**core._decision_inputs(None), "willing": willing, "reunion": reunion},
            "utilities": {"stand_up": chance, "stay": SCALE - chance},
            "probabilities": {"stand_up": chance, "stay": SCALE - chance},
        },
    )
    if reunion:
        s.reunion_until = None
    return excursion.set_out(core, reason, parents=(decision.event_id,))


def undock(core: DuckCore, by: str, parents: tuple[str, ...] = ()) -> None:
    s = core.s
    if not s.nested:
        return
    s.nested = False
    core._emit("nest.undocked", {"by": by, "battery": s.battery, "docks": s.docks}, parents=parents)


# ---------------------------------------------------------------------------- going home


def start_homing(core: DuckCore, reason: str, parents: tuple[str, ...] = ()) -> bool:
    """nav.home_start: an errand back to the nest, walked leg by leg from here."""
    s = core.s
    if s.nested:
        return False
    event = core._emit(
        "nav.home_start",
        {
            "reason": reason,
            "battery": s.battery,
            "threshold": threshold(core),
            "dist_mm": dist_mm(core),
            "pose_err_mm": s.pose_err_mm,
            "family": s.family,
            "phase": s.phase,
            # Put down here by a hand (not walked here): the reserve was not its to keep.
            "hand_placed": s.hand_placed,
        },
        parents=parents,
    )
    s.homing = {
        "reason": reason,
        "stage": "approach",
        "tries": 0,
        "legs": 0,
        "started": s.now,
        "from_mm": dist_mm(core),
        "event": event.event_id,
        "turns": 0,
    }
    if s.posture == "sit":
        if not _stand(core, "home", (event.event_id,)):
            return True  # it could not get up; it tries again in a minute or two
    moments.home_start(core, reason, int(s.homing["from_mm"]), event.event_id)
    if s.posture == "stand":
        next_leg(core)  # (a goofy wrong turn is walking already: the way home comes after)
    return True


def _stand(core: DuckCore, reason: str, parents: tuple[str, ...]) -> bool:
    """Get up for the errand (never while resting after failed tries to stand)."""
    if core._until(core.s.stand_block_until):
        return False
    core._perform("stand_up", reason=reason, parents=parents, force_sound=())
    return core.s.posture == "stand"


def errand_minute(core: DuckCore) -> bool:
    """The errand home is under way: its legs run as time passes. Seated (a hand held it,
    it could not stand, a fall it got up from), it gets going again when it can."""
    s = core.s
    h = s.homing
    if h is None:
        return False
    if s.posture in ("stand", "walk"):
        return True
    if s.posture == "sit" and not core._until(s.napping_until):
        why = _can_walk(core)
        if why is None and not core._until(s.stand_block_until):
            if _stand(core, "home", (str(h["event"]),) if h.get("event") else ()):
                next_leg(core)
        elif why == "battery":
            strand(core, "battery")
        elif why not in (None, "busy"):
            s.homing = None  # it cannot walk home now at all: the errand is off
            return False
    return True


def _abandon_alone(core: DuckCore) -> bool:
    """Walking home is allowed only for a while after the family went out."""
    s = core.s
    if s.family not in ("away", "unknown") or s.family_since is None:
        return False
    # A leg that starts now must also end within the allowed time.
    left = timedelta(minutes=int(N["alone_home_min"])) - (s.now - s.family_since)
    return left < timedelta(seconds=int(_e().WALK_S_MAX))


def next_leg(core: DuckCore) -> None:
    """The next step of the errand: a leg toward the nest, the last leg in, turning round,
    or sitting down onto the contacts."""
    s = core.s
    h = s.homing
    if h is None or s.posture != "stand":
        return  # (fallen, or sat down on the way: the errand resumes from its minute)
    core.s.errand_step += 1
    why = _can_walk(core)
    if why is not None or _abandon_alone(core):
        if why == "battery":
            strand(core, "battery")
            return
        if why == "night":
            s.homing = None
            strand(core, "bedtime")
            return
        if why in ("unplaced", "stranded") or _abandon_alone(core):
            s.homing = None
        _sit(core, "wait")
        return
    if moments.home_pause(core):
        return  # it stopped to preen (it forgot where it was going): the next leg after
    h["legs"] = int(h["legs"]) + 1
    if int(h["legs"]) > 20:
        strand(core, "dock_failed")  # lost on the way (never expected): ask for a hand
        return
    stage = str(h["stage"])
    dist = dist_mm(core)
    if stage == "backoff":
        target = (int(N["backoff_mm"]), 0)
        dx, dy = target[0] - s.pos_x, target[1] - s.pos_y
        if isqrt(dx * dx + dy * dy) <= 200:
            h["stage"] = stage = "approach"
        else:
            _leg(core, target, "home")
            return
    if stage == "approach":
        if dist <= int(N["approach_mm"]):
            if core.hw.marker:
                bearing = atan2_mrad(-s.pos_y, -s.pos_x) if dist else s.heading
                core._emit(
                    "sense.nest_seen",
                    {
                        "bearing_mrad": signed_mrad(bearing - s.heading),
                        "range_mm": dist,
                    },
                    source="body",
                )
                s.pose_err_mm = min(s.pose_err_mm, 60)
            h["stage"] = stage = "dock"
        else:
            _leg(core, (0, 0), "home")
            return
    if stage == "dock":
        if not h.get("dock_guess"):
            h["dock_guess"] = True
            moments.dock_leg(core, int(h.get("from_mm", dist)))
        # One leg in (a leg is at least ~22 cm, so from closer it would only overshoot).
        if dist >= int(N["dock_leg_min_mm"]) and not h.get("dock_leg"):
            plan = core._plan_leg_toward((0, 0), "dock")
            if plan["verb"] == "wander":
                h["dock_leg"] = True
            _go(core, plan, "dock")
            return
        h["stage"] = stage = "circle"
    if stage == "circle":
        # Ring contacts charge at any heading once it sits in the middle, so it sits down
        # the way it walked in: turning round on the spot is only marching in place for the
        # official walk (it barely turns there, official physics 2026-09-26).
        dock_try(core)
        return


def _leg(core: DuckCore, target: tuple[int, int], purpose: str) -> None:
    plan = core._plan_leg_toward(target, purpose)
    _go(core, plan, purpose)


def _go(core: DuckCore, plan: dict[str, Any], purpose: str) -> None:
    s = core.s
    low, high = N["home_pause_s"]
    s.leg_pause_s = int(low) + rng.pick_index(core._rand("nest.pause"), int(high) - int(low) + 1)
    core._walk_leg(plan, reason="home" if purpose != "circle" else "circle")


def dock_try(core: DuckCore) -> None:
    """Sit down onto the contacts (body.dock says whether they touched)."""
    s = core.s
    h = s.homing or {"tries": 0, "started": s.now, "from_mm": dist_mm(core), "reason": "self"}
    moments.dock(core)  # (now and then a look left and right first)
    core._perform("sit_down", reason="dock", force_sound=())
    tries = int(h["tries"]) + 1
    # With the marker in sight the last few centimetres are duck-body's closed loop.
    err = 0 if core.hw.marker else s.pose_err_mm
    chance = core.hw.dock_ppm * clamp(SCALE - err * SCALE // 800) // SCALE
    raw = core._rand("dock.try")
    ok = (raw * content.PPM) >> 64 < chance
    attempt = core._emit(
        "nest.dock_try",
        {
            "try": tries,
            "ok": ok,
            "err_mm": err,
            "marker": core.hw.marker,
            "chance_ppm": chance,
            "counter": core.counters["dock.try"],
            "draw": rng.unit(raw),
            "dist_mm": dist_mm(core),
        },
    )
    core._emit(
        "body.dock",
        {"contact": ok, "try": tries, "source": "sim"},
        source="body",
        parents=(attempt.event_id,),
    )
    if ok:
        docked(core, "self", tries, h)
        return
    moments.dock_result(core, False, tries, attempt)
    h["tries"] = tries
    # It bumped into the pad: at least it knows where the nest is now.
    s.pose_err_mm = min(s.pose_err_mm, 100)
    E = _e()
    if h.get("reason") == "retry" and (_abandon_alone(core) or tries >= int(N["dock_tries"])):
        # A quiet retry beside the nest that missed again: rest, and try again later
        # (it already asked for a hand).
        s.homing = None
        s.stranded = {"reason": "dock_failed", "since": s.now, "battery": s.battery}
        return
    if tries >= int(N["dock_tries"]) or s.battery < E.MIN_MOTION_BATTERY:
        strand(core, "dock_failed")
        return
    # dock-retry-v1: it cannot walk backwards, so it stands, turns out, walks out a
    # little, turns round and comes in again.
    h["stage"] = "backoff"
    h["turns"] = 0
    h["legs"] = 0
    h["dock_leg"] = False
    if _stand(core, "dock_retry", (attempt.event_id,)):
        next_leg(core)


def docked(core: DuckCore, by: str, tries: int = 0, homing: dict[str, Any] | None = None) -> Event:
    s = core.s
    from_mm = int((homing or {}).get("from_mm", dist_mm(core)))
    started = (homing or {}).get("started", s.now)
    s.nested = True
    s.floor = True
    s.unplaced = False
    s.stranded = None
    if s.need is not None and s.need.get("kind") in ("carry_me_home", "nest_help", "bedtime"):
        s.need = None
    core._place_on_nest(walked_in=by in ("self", "reseat"))
    s.pose_err_mm = 0
    s.docks += 1
    s.day_docks += 1
    event = core._emit(
        "nest.docked",
        {
            "by": by,
            "tries": tries,
            "seconds": int((s.now - started).total_seconds()),
            "battery": s.battery,
            "from_mm": from_mm,
            "reason": (homing or {}).get("reason"),
            "docks": s.docks,
        },
    )
    if by == "self" and homing is not None:
        moments.dock_result(core, True, tries, event)
    moments.docked(core, by, tries, int((homing or {}).get("cm", 0)), event)
    s.homing = None
    return event


def strand(core: DuckCore, reason: str) -> None:
    """It cannot get home by itself: sit down where it is and ask for a hand."""
    from duckmind.engines.v4_0.duckcore import excursion

    s = core.s
    if s.stranded is not None:
        return
    if s.excursion is not None:
        excursion.end(core, "stranded", decide=False)
    s.homing = None
    _sit(core, "stranded")
    if s.nested:
        return  # it sat down right onto the contacts: home after all
    s.stranded = {"reason": reason, "since": s.now, "battery": s.battery}
    event = core._emit(
        "nest.stranded",
        {
            "reason": reason,
            "battery": s.battery,
            "dist_mm": dist_mm(core),
            "pose": core._pose_list(),
        },
    )
    kind = {"battery": "carry_me_home", "dock_failed": "nest_help"}.get(reason, "bedtime")
    call_for_help(core, kind, (event.event_id,))


def call_for_help(core: DuckCore, kind: str, parents: tuple[str, ...]) -> None:
    """A need (never an attention bid: no back-off, counted apart)."""
    s = core.s
    s.need = {"kind": kind, "since": s.now}
    sounds = [] if s.phase in ("night",) else ["inquire", "coo"]
    bid = core._emit(
        "duck.bid",
        {
            "kind": kind,
            "need": True,
            "sounds": sounds,
            "text": content.phrase_text(tuple(sounds)) if sounds else "",
        },
        parents=parents,
    )
    core._emit("owner.notice", {"kind": kind, "text": BID_TEXT[kind]}, parents=(bid.event_id,))


def retry_stranded(core: DuckCore) -> None:
    """Three misses at the nest are not forever: after a short rest it tries again by
    itself (its battery would not last long sitting beside the nest). With the family out
    for a while it only stands and sits again right where it is (no legs to walk)."""
    E = _e()
    s = core.s
    st = s.stranded
    if st is None or st.get("reason") != "dock_failed" or s.posture != "sit":
        return
    if s.now - st["since"] < timedelta(minutes=RETRY_AFTER_MIN):
        return
    if s.battery < E.MIN_MOTION_BATTERY + 100 or _can_walk(core) not in (None, "stranded"):
        return
    s.stranded = None
    if _abandon_alone(core) or dist_mm(core) <= int(N["dock_leg_min_mm"]):
        # Right at the nest: stand, and sit down onto it again.
        s.homing = {
            "reason": "retry",
            "stage": "circle",
            "tries": 0,
            "legs": 0,
            "started": s.now,
            "from_mm": dist_mm(core),
            "event": "",
            "turns": 3,  # no turning legs: only sitting down again
        }
        if _stand(core, "dock_retry", ()):
            dock_try(core)
        else:
            s.homing = None
            s.stranded = st
        return
    start_homing(core, "retry")


def reseat(core: DuckCore) -> bool:
    """Sat back down right where it stood up in the nest: the contacts touch again."""
    s = core.s
    if s.nested or not s.floor or s.unplaced:
        return False
    if dist_mm(core) > int(N["funnel_mm"]):
        return False  # (ring contacts: any heading touches once it sits in the middle)
    docked(core, "reseat")
    return True
